    tmp_R_TRIG_finished : R_TRIG;
END_VAR

VAR CONSTANT
    STATE_IDLE      : INT := 0;
    STATE_CLEANING  : INT := 1;
    STATE_FILLING   : INT := 2;
    STATE_CAPPING   : INT := 3;
    STATE_PACKING   : INT := 4;
    STATE_COMPLETED : INT := 5;
